(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin(x*0.04-t*0.5)*5 + Math.cos(y*0.035+t*0.4)*4;
  const w2y = Math.cos(y*0.04+t*0.45)*5 + Math.sin(x*0.038-t*0.55)*4;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 1.2],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 2.5],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 3.8],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 5.0],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.7],
    [60+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*50, 0.11, 2.1, 4.2],
    [420+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75)*55, 0.085, 1.8, 2.9]
  ];
  let aS=0, iS=0, aR=0, iR=0;
  for (const [sX,sY,f,sp,ph] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const w = Math.sin(d*0.03+t*0.8)*0.3+1;
    aS += Math.sin(d*f*w - t*sp + ph);
    iS += Math.sin(d*f*0.7*w + t*sp*0.6 + 1.5 + ph);
    aR += Math.sin(d*f*1.5*w - t*sp*1.3 + ph*0.5);
    iR += Math.cos(d*f*0.5*w + t*sp*0.4 + ph*0.8);
  }
  const act=aS/8, inh=iS/8, act2=aR/8, inh2=iR/8;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2
    + Math.sin(sx*0.07*sy*0.0001+t*0.6)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    + Math.sin(dist*0.08-ang*2-t*2.2)*0.2;
  const moire = Math.sin(dist*0.12)*Math.sin(ang*5+t*0.8)*0.25;
  const reaction = Math.tanh((act-inh*0.7+bg*0.3+spiral+moire)*2.2);
  const reaction2 = Math.tanh((act2-inh2*0.6+spiral*0.5-bg*0.2)*1.8);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const weave = Math.sin(sx*0.2+reaction*3)*Math.sin(sy*0.2-reaction2*3)*0.15;
  const blend = reaction*0.5 + reaction2*0.2 + cell*0.2 + weave*0.1;
  const v = blend*0.5+0.5;
  const dx = Math.cos(ang+reaction*2), dy = Math.sin(ang+reaction2*2);
  const vR = (v + dx*0.04)*0.5+0.5, vB = (v - dx*0.04)*0.5+0.5;
  const pal = [[5,12,55],[12,55,95],[18,110,125],[35,165,145],[160,190,80],[220,175,55],[215,110,65],[175,55,70],[100,25,55],[40,15,45],[5,12,55]];
  const gC = v => { const idx=v*(pal.length-1); const i=Math.min(idx|0,pal.length-2); const f=idx-i; return [pal[i][0]+(pal[i+1][0]-pal[i][0])*f, pal[i][1]+(pal[i+1][1]-pal[i][1])*f, pal[i][2]+(pal[i+1][2]-pal[i][2])*f]; };
  const cM=gC(v), cR=gC(Math.max(0,Math.min(1,vR))), cB=gC(Math.max(0,Math.min(1,vB)));
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15;
  const edge=Math.abs(reaction)>0.65?1.2:Math.abs(reaction2)>0.6?1.1:1.0;
  const glow=Math.max(0, 1-Math.abs(reaction)*1.5)*0.15;
  return [
    Math.min(255, ((cM[0]*0.7+cR[0]*0.3)*lum*edge + glow*80)|0),
    Math.min(255, ((cM[1]*0.85+cR[1]*0.08+cB[1]*0.07)*lum*edge + glow*60)|0),
    Math.min(255, ((cM[2]*0.7+cB[2]*0.3)*lum*edge + glow*100)|0)
  ];
}
